package com.example.gettingstarted;

import example.avro.User;

/**
 * The three users of the Getting Started guide, each created in one of the guide's three ways (section 1.4).
 * <p>
 * {@code example.avro.User} is generated by the avro-maven-plugin from {@code src/main/resources/avro/user.avsc}.
 */
public final class Users {

    private Users() {
    }

    /** The no-argument constructor and setters. Fields you don't set stay null: Alyssa has no favourite colour. */
    public static User alyssa() {
        User user1 = new User();
        user1.setName("Alyssa");
        user1.setFavoriteNumber(256);
        // Leave favorite color null
        return user1;
    }

    /** The all-arguments constructor. Arguments are matched to fields by position, in schema order. */
    public static User ben() {
        return new User("Ben", 7, "red");
    }

    /**
     * The builder. It checks every field when you call {@code build()}. favorite_number may be null, but it has no
     * default, so the builder needs it set explicitly, even to null.
     */
    public static User charlie() {
        return User.newBuilder()
            .setName("Charlie")
            .setFavoriteColor("blue")
            .setFavoriteNumber(null)
            .build();
    }
}
